import itertools

def is_brbr(colors):
    n = len(colors)
    for i, j, k, l in itertools.combinations(range(n), 4):
        if colors[i] == 'B' and colors[j] == 'R' and colors[k] == 'B' and colors[l] == 'R':
            return True
    return False

def get_all_valid_colorings(n):
    valid = []
    for colors in itertools.product('RB', repeat=n):
        # The condition is for ANY 4 points in clockwise order.
        # Since it's a circle, we must check all rotations.
        is_valid = True
        for shift in range(n):
            rotated = colors[shift:] + colors[:shift]
            if is_brbr(rotated):
                is_valid = False
                break
        if is_valid:
            valid.append(colors)
    return valid

for n in range(3, 6):
    valid = get_all_valid_colorings(n)
    print(f"n={n}, number of valid colorings: {len(valid)}")
